def wilson(k, n):
    z = 1.96
    denominator = 1 + z*z/n
    center = (k/n + z*z/(2*n))/denominator
    radius = z*math.sqrt(k/n*(1-k/n)/n + z*z/(4*n*n))/denominator
    return [round(center-radius, 6), round(center+radius, 6)]

